import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <section className={styles.container}>
        
        <section className="text-terracota bg-beige p-12 mb-6 shadow-lg">
          <h2 className=" h2_mobile sm:h2_desk text-center mb-6">{t("aboutUs.section1.title")}</h2>
          <article className=" body_mobile sm:body_desk mb-6"
            dangerouslySetInnerHTML={{ __html: t("aboutUs.section1.content") || "" }}
          />
          <p className="h3_mobile sm:h3_desk flex justify-end">{t("aboutUs.section1.author")}</p>
        </section>
        <section className="text-warm_ivory bg-dark_gray p-12 mb-6 shadow-lg">
          <h2 className=" h2_mobile sm:h2_desk text-center mb-6">{t("aboutUs.section2.title")}</h2>
          <article className=" body_mobile sm:body_desk mb-6"
            dangerouslySetInnerHTML={{ __html: t("aboutUs.section2.content") || "" }}
          />
          <p className="h3_mobile sm:h3_desk flex justify-end">{t("aboutUs.section2.author")}</p>
        </section>


      </section>
    </Layout>
  )
}

export default IndexPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "",
  section: "",
  title: "",
  paragraph: ""
}
